function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Start by painting the sky using a light blue color with a slight bleed
  brush.fillBleed(0.3); // Adjust the amount of bleed to create a soft, gradient sky
  brush.beginShape();
  brush.vertex(0, 0); // Top-left of the sky
  brush.vertex(400, 0); // Top-right of the sky
  brush.vertex(200, 100); // Middle of the sky
  brush.endShape(true);

  // Move to the next section of the canvas to paint the green hills
  translate(200, 100);

  // Use a green color with a medium bleed to create the hills
  brush.fillBleed(0.5); // Adjust the amount of bleed to create a green hill
  brush.beginShape();
  brush.vertex(0, 0); // Bottom-left of the hill
  brush.vertex(400, 0); // Bottom-right of the hill
  brush.vertex(200, 200); // Top of the hill
  brush.endShape(true);

  // Add more hills by translating to the next section of the canvas
  translate(200, 200);

  // Use a darker green color with a slightly higher bleed to create a more pronounced hill
  brush.fillBleed(0.7); // Adjust the amount of bleed to create a more pronounced hill
  brush.beginShape();
  brush.vertex(0, 0); // Bottom-left of the hill
  brush.vertex(400, 0); // Bottom-right of the hill
  brush.vertex(200, 300); // Top of the hill
  brush.endShape(true);

  // Add more hills by translating to the next section of the canvas
  translate(200, 300);

  // Use a deep green color with a slightly higher bleed to create a more pronounced hill
  brush.fillBleed(0.9); // Adjust the amount of bleed to create a more pronounced hill
  brush.beginShape();
  brush.vertex(0, 0); // Bottom-left of the hill
  brush.vertex(400, 0); // Bottom-right of the hill
  brush.vertex(200, 400); // Top of the hill
  brush.endShape(true);

  // Add more hills by translating to the next section of the canvas
  translate(200, 400);
}
