```javascript
function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4"); // Setting the background to a light grayish white for the sunlit hills

  // Using the brush methods to create the sunset colors on the hills
  // First, create the green hills by using the fillBleed method with a moderate amount of bleed
  brush.fillBleed(0.7);
  brush.beginShape();
  brush.vertex(0, 0); // Starting the green hill
  brush.vertex(100, 50); // Creating a green hill
  brush.vertex(200, 100); // Creating the other part of the green hill
  brush.endShape(true);

  // Next, use the fillBleed method with a lower amount of bleed to create the darker green hills
  brush.fillBleed(0.4);
  brush.beginShape();
  brush.vertex(0, 100); // Starting the darker green hill
  brush.vertex(100, 150); // Creating a darker green hill
  brush.vertex(200, 200); // Creating the other part of the darker green hill
  brush.endShape(true);

  // Finally, create the blue sky using the fill method with a moderate amount of opacity
  brush.fillBleed(0.3);
  brush.beginShape();
  brush.vertex(0, 200); // Starting the blue sky
  brush.vertex(100, 250); // Creating the blue sky
  brush.vertex(200, 300); // Creating the other part of the blue sky
  brush.endShape(true);
}
