function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Painting goes here

  // Shape representing the hills
  brush.fillBleed(0.3);  // Use a lighter color for the hills
  brush.beginShape();
  brush.vertex(0, 0);   // Top of the hill
  brush.vertex(100, 50);  // Middle of the hill
  brush.vertex(200, 0);   // Bottom of the hill
  brush.endShape(true);

  // Shape representing the sky (a lighter blue color)
  brush.fillBleed(0.5);  // Use a slightly darker color for the sky
  brush.beginShape();
  brush.vertex(0, 0);   // Top of the sky
  brush.vertex(100, 100);  // Middle of the sky
  brush.vertex(200, 150);   // Bottom of the sky
  brush.endShape(true);

  // Shape representing the sun (a bright yellow color)
  brush.fillBleed(0.8);  // Use a bright color for the sun
  brush.beginShape();
  brush.vertex(150, 100);   // Top of the sun
  brush.vertex(180, 120);  // Middle of the sun
  brush.vertex(200, 100);   // Bottom of the sun
  brush.endShape(true);

  // Add some texture to the hills for a more realistic look
  brush.fillBleed(0.3);  // Use a slightly darker texture
  brush.beginShape();
  brush.vertex(0, 0);   // Top of the hill
  brush.vertex(100, 150);  // Middle of the hill
  brush.vertex(200, 100);   // Bottom of the hill
  brush.endShape(true);
}
